gpu_pipeline_executor::gpu_pipeline_executor(
  exec::thread_pool_config config,
  cucascade::memory::memory_space* mem_space,
  exec::publisher<std::unique_ptr<task_request>> task_request_publisher,
  sirius::parallel::downgrade_executor* downgrade_executor,
  std::shared_ptr<const telemetry::telemetry_context> telemetry_context)
  : sirius::parallel::itask_executor(
      config, std::move(telemetry_context), mem_space->get_device_id()),
    _stream_pool(rmm::cuda_device_id{mem_space->get_device_id()}, config.num_threads),
    _task_request_publisher(std::move(task_request_publisher)),
    _memory_space(mem_space),
    _downgrade_executor(downgrade_executor)
{
}

gpu_pipeline_executor::~gpu_pipeline_executor() { stop(); }

absl::AnyInvocable<void() noexcept> gpu_pipeline_executor::get_per_thread_init()
{
  int device_id          = _memory_space->get_device_id();
  auto thread_id_counter = std::make_shared<std::atomic<uint32_t>>(0);

  return [device_id,
          telemetry_context = _telemetry_context,
          thread_prefix     = _config.thread_name_prefix,
          thread_id_counter]() mutable noexcept {
    const int32_t thread_id = thread_id_counter->fetch_add(1, std::memory_order_relaxed);
    telemetry::thread_local_executor_thread_telemtry_init(
      *telemetry_context,
      std::format("{}-gpu{}-exec-{}", thread_prefix, device_id, thread_id),
      telemetry_context->executor_thread_group_id(device_id));

    // Per-thread init runs on a worker thread just spawned by the
    // bounded_pool. cudaSetDevice pins this thread to the executor's GPU
    // context; silent failure would cause every downstream CUDA call on this
    // thread to land on GPU 0 regardless of device_id. We cannot use
    // CUCASCADE_CUDA_TRY here because the lambda is noexcept — inline the
    // check instead.
    cudaError_t err = cudaSetDevice(device_id);
    if (err != cudaSuccess) {
      SIRIUS_LOG_ERROR("gpu_pipeline_executor per-thread init: cudaSetDevice({}) failed: {}",
                       device_id,
                       cudaGetErrorString(err));
    }
    sirius::util::enable_log_on_default_stream();
  };
}

void gpu_pipeline_executor::manager_loop()
{
  telemetry::TaskManagerLoopThreadHandleWrapper manager_thread_telemetry{
    *_telemetry_context,
    std::format("gpu-{}-exec-manager", _memory_space->get_device_id()),
    _telemetry_context->manager_thread_group_id(_memory_space->get_device_id())};

  rmm::cuda_set_device_raii set_device_guard(rmm::cuda_device_id{_memory_space->get_device_id()});
  sirius::util::enable_log_on_default_stream();
  while (_running.load()) {
    auto slot = _bounded_pool->reserve();  // block till a thread is available
    if (!slot) {
      SIRIUS_LOG_INFO("GPU Pipeline Executor: pool interrupted, stopping manager loop");
      break;
    }
    // Pull-signal backpressure: now that we hold a reserved thread slot, tell the
    // task_scheduler this device is ready for work. The scheduler will only move
    // a task out of its downgrade-visible queue into our _task_queue when a
    // ready signal has been received from us — preventing tasks from piling
    // up here where the downgrade executor can't see them.
    auto ready       = std::make_unique<task_request>();
    ready->kind      = task_request_kind::device_ready;
    ready->device_id = _memory_space->get_device_id();

    std::unique_ptr<parallel::itask> pipeline_task = nullptr;
    {
      if (!_task_request_publisher.send(std::move(ready))) {
        SIRIUS_LOG_INFO(
          "GPU Pipeline Executor: task_request channel closed, stopping manager loop");
        break;
      }
      pipeline_task = _task_queue.pop();  // block till a task is available
    }
    if (!pipeline_task) {
      SIRIUS_LOG_INFO("GPU Pipeline Executor: task queue interrupted, stopping manager loop");
      break;
    }
    auto* gpu_task = cast_to_gpu_pipeline_task(pipeline_task.get());
    if (!gpu_task) {
      SIRIUS_LOG_ERROR("GPU Pipeline Executor: Failed to cast pipeline task to gpu_pipeline_task");
      if (_completion_handler) {
        _completion_handler->report_error(
          "GPU Pipeline Executor: Failed to cast pipeline task to gpu_pipeline_task");
      }
      break;
    }

class gpu_pipeline_task_local_state : public sirius_pipeline_task_local_state {
 public:
  /**
   * @brief Construct a new gpu_pipeline_task_local_state object
   *
   * @param batch_views Vector of data batches serving as input to the pipeline
   * @param res Memory reservation for GPU resources
   */
  explicit gpu_pipeline_task_local_state(std::unique_ptr<op::operator_data> input_data,
                                         size_t start_operator_index = 0)
    : _input_data(std::move(input_data)), _start_operator_index(start_operator_index)
  {
  }

  std::unique_ptr<op::operator_data> _input_data;  ///< Input data batches for the pipeline
  size_t _start_operator_index = 0;  ///< Operator index to resume from (0 = start of pipeline)

  /**
   * @brief Set the preferred GPU device ID for this task based on data locality.
   *
   * @param device_id The GPU device ID where the majority of input data resides
   */
  void set_preferred_device_id(int device_id) { _preferred_device_id = device_id; }

  /**
   * @brief Get the preferred GPU device ID for this task.
   *
   * @return The preferred device ID, or std::nullopt if not set
   */
  [[nodiscard]] std::optional<int> get_preferred_device_id() const { return _preferred_device_id; }

  /// Number of times this task has been retried due to OOM (0 = first attempt).
  uint32_t retry_count = 0;
  /// Task ID of the original (non-retried) task; only meaningful when retry_count > 0.
  std::optional<uint64_t> original_task_id = std::nullopt;

  /// Request-size fallback used when an OOM does not expose the failed allocation size.
  static constexpr std::size_t kDefaultRetryRequestBytes = 1024 * 1024;

  void update_retry_reservation_floor_after_oom(std::size_t current_reservation_bytes,
                                                std::size_t live_allocated_bytes,
                                                std::optional<std::size_t> requested_bytes) noexcept
  {
    auto const request_bytes = requested_bytes.value_or(kDefaultRetryRequestBytes);
    auto next_floor          = memory::saturating_mul(current_reservation_bytes, 2);
    next_floor = std::max(next_floor, memory::saturating_add(live_allocated_bytes, request_bytes));
    next_floor = std::max(next_floor, kDefaultRetryRequestBytes);
    _retry_reservation_floor = std::max(_retry_reservation_floor, next_floor);
  }

  void inherit_retry_reservation_floor(const gpu_pipeline_task_local_state& previous) noexcept
  {
    _retry_reservation_floor =
      std::max(_retry_reservation_floor, previous._retry_reservation_floor);
  }

  [[nodiscard]] std::size_t get_retry_reservation_floor() const noexcept
  {
    return _retry_reservation_floor;
  }

  [[nodiscard]] std::size_t get_task_consumption_basis() const override
  {
    if (_reservation_size_info) { return _reservation_size_info->input_basis; }
    // Fallback for code paths that call this before get_estimated_reservation_size_info()
    // (e.g. tests that bypass the normal executor flow).
    return _input_data ? _input_data->get_estimated_size_in_bytes() : 0;
  }

  /**
   * @brief Estimate the bytes prepare_for_processing will allocate in the target space.
   *
   * Counts inputs that are not GPU-resident (host/disk upgrades) and, when @p target_space is
   * given, GPU-resident inputs living in a different memory space — those are cloned into the
   * target space by lock_or_prepare_batch, so their bytes are part of the task's footprint.
   * Resident scan inputs cached in HOST are also counted, since they require an upload before
   * execution.
   */
  [[nodiscard]] std::size_t get_estimated_bytes_to_materialize_input(
    const cucascade::memory::memory_space* target_space) const;

 private:
  std::optional<int> _preferred_device_id;  ///< Preferred GPU device based on data locality
  std::size_t _retry_reservation_floor = 0;
};

/**
 * @brief A task representing a unit of work in a GPU pipeline.
 *
 * This class encapsulates the necessary information to execute a task within a pipeline on the GPU.
 * These task will be created by the TaskCreator and be scheduled for execution on the
 * gpu_pipeline_executor.
 *
 * Note that this class will be further derived to represent specific types of tasks such as build,
