210	//------------------------------------------------------------------------------
211	// Task that allocates kAllocationBytes of GPU memory, holds it, then frees.
212	// If OOM occurs, throws oom_reschedule_exception for the executor to handle.
213	//------------------------------------------------------------------------------
214	constexpr std::size_t kAllocationBytes = 400ULL * 1024 * 1024;  // 400 MB
215	constexpr auto kHoldDuration           = std::chrono::milliseconds(30);
216	
217	class oom_test_task : public oom_test_task_base {
218	 public:
219	  using oom_test_task_base::oom_test_task_base;
220	
221	  void execute(rmm::cuda_stream_view stream) override
222	  {
223	    auto& global = _global_state->cast<oom_test_global_state>();
224	    auto& local  = _local_state->cast<sirius::pipeline::gpu_pipeline_task_local_state>();
225	
226	    auto guard = setup_allocator(stream, "OOM test task");
227	    if (!guard) {
228	      global.completed_count.fetch_add(1, std::memory_order_relaxed);
229	      return;
230	    }
231	    auto* allocator = guard->allocator;
232	
233	    void* allocation = nullptr;
234	    try {
235	      allocation = allocator->allocate(stream, kAllocationBytes, alignof(std::max_align_t));
236	    } catch (const rmm::out_of_memory&) {
237	      global.oom_count.fetch_add(1, std::memory_order_relaxed);
238	      throw sirius::pipeline::oom_reschedule_exception(
239	        std::move(local._input_data), 0, "OOM in test task allocation");
240	    }
241	
242	    // Hold the memory for a while to create pressure on concurrent tasks.
243	    std::this_thread::sleep_for(kHoldDuration);
244	
245	    allocator->deallocate(stream, allocation, kAllocationBytes, alignof(std::max_align_t));
246	    global.completed_count.fetch_add(1, std::memory_order_relaxed);
247	  }
