254	      static_cast<sirius::pipeline::gpu_pipeline_task_local_state*>(local_state.release()));
255	    return std::make_unique<oom_test_task>(
256	      task_id,
257	      std::move(typed_local),
258	      std::dynamic_pointer_cast<oom_test_global_state>(_global_state));
259	  }
