343	// ---------------------------------------------------------------------------
344	// Memory layout for the reschedule test:
345	//   Allocation    = 400 MB per task (much larger than the 50 MB reservation)
346	//
347	// With 3 threads, all 3 tasks start concurrently.
348	// Accounting after 3 reservations: 150 MB
349	// First  allocation (+350 MB overflow): total =  500 MB ≤ 1100 → OK
350	// Second allocation (+350 MB overflow): total =  850 MB ≤ 1100 → OK
351	// Third  allocation (+350 MB overflow): total = 1200 MB > 1100 → OOM!
352	//
353	// The OOM'd task gets rescheduled. After the first two complete, enough
354	// accounting headroom is freed for the rescheduled task to succeed.
355	// (Note: cucascade's cross-boundary deallocation accounting leaves some
356	//  residual in _total_allocated_bytes, hence the extra capacity margin.)
357	// ---------------------------------------------------------------------------
358	TEST_CASE("GPU pipeline executor reschedules tasks on OOM", "[gpu_pipeline_executor][oom]")
359	{
360	  oom_test_fixture f;
361	  if (!f.setup(3, "oom-test")) {
362	    WARN("Skipping OOM reschedule test — no GPU available.");
363	    return;
364	  }
365	
366	  auto global_state = std::make_shared<oom_test_global_state>();
367	
368	  const int num_tasks = 3;
369	  std::atomic<int> dispatched{0};
370	
371	  f.executor->start();
372	
373	  // Post-v1.0 push-model (commit 90dc104): gpu_pipeline_executor no longer publishes
374	  // task_requests. Schedule tasks directly onto the executor instead of waiting on
375	  // f.request_channel.get(). The request_channel is kept wired to preserve the
376	  // fixture API but is not used at runtime.
377	  std::thread request_handler([&]() {
378	    while (dispatched.load(std::memory_order_relaxed) < num_tasks) {
379	      auto local_state = std::make_unique<sirius::pipeline::gpu_pipeline_task_local_state>(
380	        std::make_unique<sirius::op::pipelineable_operator_data>(
381	          std::vector<std::shared_ptr<cucascade::data_batch>>{}));
382	      auto task = std::make_unique<oom_test_task>(
383	        static_cast<uint64_t>(dispatched.load(std::memory_order_relaxed)),
384	        std::move(local_state),
385	        global_state);
386	      f.executor->schedule(std::move(task));
387	      dispatched.fetch_add(1, std::memory_order_relaxed);
388	    }
389	  });
390	
391	  //--------------------------------------------------------------------------
392	  // Wait for all tasks to complete (including rescheduled ones)
393	  //--------------------------------------------------------------------------
394	  auto start_time = std::chrono::steady_clock::now();
395	  auto timeout    = std::chrono::seconds(30);
396	  while (global_state->completed_count.load(std::memory_order_relaxed) < num_tasks) {
397	    std::this_thread::sleep_for(std::chrono::milliseconds(50));
398	    if (std::chrono::steady_clock::now() - start_time > timeout) {
399	      f.executor->stop();
400	      f.request_channel.close();
401	      request_handler.join();
402	      FAIL("Timed out waiting for OOM rescheduled tasks to complete. "
403	           << "Completed: " << global_state->completed_count.load()
404	           << ", OOM count: " << global_state->oom_count.load());
405	    }
406	  }
407	
408	  f.executor->stop();
409	  f.request_channel.close();
410	  request_handler.join();
411	
412	  //--------------------------------------------------------------------------
413	  // Validate results
414	  //--------------------------------------------------------------------------
415	  if (global_state->error_count.load(std::memory_order_relaxed) > 0) {
416	    std::lock_guard<std::mutex> lock(global_state->error_mutex);
417	    for (const auto& error : global_state->errors) {
418	      INFO(error);
419	    }
420	  }
421	
422	  REQUIRE(global_state->error_count.load(std::memory_order_relaxed) == 0);
423	  REQUIRE(global_state->completed_count.load(std::memory_order_relaxed) == num_tasks);
424	  // At least one task should have OOM'd and been rescheduled
425	  REQUIRE(global_state->oom_count.load(std::memory_order_relaxed) >= 1);
426	
427	  INFO("OOM reschedule test passed: " << global_state->oom_count.load() << " task(s) rescheduled, "
428	                                      << num_tasks << " completed successfully");
429	}
